// 1. Place E-Commerce Order (Saga Entrypoint)
POST /api/v1/orders
Headers:
  Idempotency-Key: checkout_usr881_cart42
Request:
{
  "customer_id": "usr_881",
  "shipping_address_id": "addr_102",
  "payment_method_id": "pm_visa_9912",
  "items": [
    { "sku_id": "SKU-PS5-PRO", "quantity": 1, "unit_price_cents": 69900 }
