  [PK ] reservation_id         UUID
  [FK ] order_id               UUID
  [IDX] sku_id                 VARCHAR(64)
        reserved_qty           INT
        status                 ENUM('RESERVED','COMMITTED','RELEASED')
}

// Relationships: orders --(1 : N (line items))--> order_items --(1 : N (saga stock holds))--> inventory_reservations

