// 1. Place Limit Order
POST /api/v1/orders
Headers:
  X-Client-Order-Id: cl_ord_991823
Request:
{
  "account_id": "acct_7712",
  "symbol": "AAPL",
  "side": "BUY",
  "order_type": "LIMIT",
  "time_in_force": "GTC",
